import sqlite3
from contextlib import asynccontextmanager
from fastapi import FastAPI, HTTPException, status
from pydantic import BaseModel, Field, field_validator
import re

DATABASE_NAME = "db.sqlite3"

def get_db() -> sqlite3.Connection:
    conn = sqlite3.connect(DATABASE_NAME)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode=WAL")
    return conn

def init_db():
    with get_db() as conn:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS noise_measurements (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                zip_code TEXT NOT NULL,
                decibels REAL NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        conn.commit()

async def lifespan(app: FastAPI):
    init_db()
    yield

app = FastAPI(
    title="NeighborhoodAverageNoiseReporter",
    description="Residents submit a noise level measurement (decibels) and their ZIP code. The service maintains a running average per ZIP code and exposes a public endpoint to retrieve the current average noise level for a given ZIP code.",
    version="1.0.0",
    lifespan=lifespan,
)

ZIP_CODE_PATTERN = re.compile(r"^\d{5}(-\d{4})?$")

class NoiseSubmission(BaseModel):
    zip_code: str = Field(..., description="ZIP code of the measurement location")
    decibels: float = Field(..., description="Noise level in decibels")

    @field_validator("zip_code")
    @classmethod
    def validate_zip_code(cls, v: str) -> str:
        if not ZIP_CODE_PATTERN.match(v):
            raise ValueError("Invalid ZIP code format. Must be 5-digit or ZIP+4.")
        return v

    @field_validator("decibels")
    @classmethod
    def validate_decibels(cls, v: float) -> float:
        if v < 0:
            raise ValueError("Decibels must be a non-negative number.")
        return v

class NoiseAverageResponse(BaseModel):
    zip_code: str
    average: float

@app.post("/noise", status_code=status.HTTP_201_CREATED)
def submit_noise(submission: NoiseSubmission):
    try:
        with get_db() as conn:
            conn.execute(
                "INSERT INTO noise_measurements (zip_code, decibels) VALUES (?, ?)",
                (submission.zip_code, submission.decibels),
            )
            conn.commit()
    except Exception as e:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="Invalid input",
        )
    return {"message": "Measurement recorded successfully"}

@app.get("/noise/{zip_code}", response_model=NoiseAverageResponse)
def get_noise_average(zip_code: str):
    if not ZIP_CODE_PATTERN.match(zip_code):
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="Invalid ZIP code format",
        )
    try:
        with get_db() as conn:
            row = conn.execute(
                "SELECT AVG(decibels) as average FROM noise_measurements WHERE zip_code = ?",
                (zip_code,),
            ).fetchone()
            if row is None or row["average"] is None:
                raise HTTPException(
                    status_code=status.HTTP_404_NOT_FOUND,
                    detail="No data available for the specified ZIP code",
                )
            return NoiseAverageResponse(zip_code=zip_code, average=row["average"])
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="Invalid ZIP code format",
        )

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=5000)
